  "app.ab.2": "पैसे आले आणि गेले: पेमेंट एकदा लिहा आणि ते चुकते करत असलेल्या बिलांवर टिक करा. थोडे-थोडे पेमेंट आणि ॲडव्हान्स आपोआप सांभाळले जातात, आणि ग्राहकाने कापलेला TDS ही मोजला जातो.",
