  'td.catch': 'या पेमेंटमुळे वर्षाची एकूण रक्कम मर्यादेपेक्षा जास्त होते, म्हणून TDS संपूर्ण एकूण रकमेवर काढला जातो, आधी TDS शिवाय दिलेले {y} धरून. त्यातील काहींवर TDS आधीच कापला असेल तर फक्त फरक कापा.',
  'td.nopan': 'वैध PAN नसेल तर दर 20% किंवा नेहमीच्या दराच्या दुप्पट, जो जास्त असेल तो (मालाच्या खरेदीसाठी 5%). घेणाऱ्याकडून PAN मागा.',
