  'td.q': 'तुमची गेल्या वर्षाची उलाढाल ₹10 कोटींपेक्षा जास्त असेल तरच कापा, आणि या विक्रेत्याकडून वर्षभराच्या खरेदीतील ₹50 लाखांवरील भागावरच.',
  'td.ib': 'टॅक्स ऑडिट नसलेल्या व्यक्तीने दिलेल्या भाड्यावर TDS एकदाच कापला जातो, वर्षाच्या किंवा भाडेकराराच्या शेवटच्या महिन्याच्या भाड्यातून.',
  'td.oldnote': '1 एप्रिल 2026 पूर्वीच्या पेमेंटसाठी Income-tax Act, 1961 लागू आहे: जुना कलम नंबर वापरा.',
