  "b2.farule1": "खात्यांचा घसारा कंपनीज ॲक्ट, 2013 च्या शेड्यूल II नुसार आहे: प्रत्येक प्रकारच्या ॲसेटचे उपयुक्त आयुष्य ठरलेले आहे (उदा. कॉम्प्युटर 3 वर्षे, फर्निचर 10 वर्षे, प्लांट आणि मशिनरी 15 वर्षे, कार 8 वर्षे), उरलेली व्हॅल्यू सहसा किंमतीच्या 5% पेक्षा जास्त नसते, आणि वर्षाच्या मध्यात जोडलेल्या किंवा विकलेल्या ॲसेटवर फक्त वापराच्या दिवसांचा घसारा लागतो. स्ट्रेट लाइन (SLM: दरवर्षी समान रक्कम) किंवा रिटन डाउन व्हॅल्यू (WDV: उरलेल्या रकमेवर ठरलेला रेट) निवडा. प्रोप्रायटर आणि फर्म बहुतेक हीच पद्धत वापरतात; निर्णय तुमचे अकाउंटंट घेतात.",
  "b2.farule2": "इन्कम टॅक्स घसारा प्रत्येक ब्लॉकचा वेगळा काढला जातो: ब्लॉक रेटवर रिटन डाउन व्हॅल्यू (उदा. प्लांट आणि मशिनरी 15%, फर्निचर 10%, कॉम्प्युटर 40%), वर्षात 180 दिवसांपेक्षा कमी वापरलेल्या ॲसेटवर अर्धा रेट, आणि विक्रीचे पैसे ब्लॉकमधून वजा होतात. हे फक्त इन्कम टॅक्स रिटर्नसाठी आहे, खात्यात कधीच टाकले जात नाही. भरलेले रेट नेहमीचे ब्लॉक रेट आहेत: तुमच्या अकाउंटंटकडून खात्री करा, विशेषतः 1 एप्रिल 2026 पासून इन्कम-टॅक्स ॲक्ट, 2025 खालील वर्षांसाठी.",
  "b2.farule3": "तुम्ही 'घसारा टाका' दाबल्यावरच घसारा तुमच्या खात्यात जातो: वर्षाच्या शेवटच्या दिवसाची (किंवा वर्षाच्या मध्यात आजची) जर्नल एंट्री घसाऱ्याला डेबिट करते आणि प्रत्येक ॲसेट कमी करते. नंतर ॲसेट बदलले तर पुन्हा टाका, फक्त फरक जोडला जाईल.",
